CREATE SCHEMA IF NOT EXISTS accounting;

CREATE TABLE IF NOT EXISTS accounting.partial_reconciles (
    id UUID NOT NULL DEFAULT gen_random_uuid(),
    company_id UUID NOT NULL,
    debit_move_id UUID NOT NULL,
    credit_move_id UUID NOT NULL,
    full_reconcile_id UUID,
    exchange_move_id UUID,
    amount NUMERIC(18, 2) NOT NULL,
    debit_amount_currency NUMERIC(18, 2) CHECK (debit_amount_currency >= 0),
    credit_amount_currency NUMERIC(18, 2) CHECK (credit_amount_currency >= 0),
    currency TEXT NOT NULL DEFAULT 'IDR',
    max_date DATE NOT NULL,
    origin reconcile_origin NOT NULL DEFAULT 'manual',
    source_type TEXT,
    source_id UUID,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL,
    metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
    PRIMARY KEY (id),
    -- An edge always moves a positive amount and never loops a line onto itself.
    CONSTRAINT chk_partial_reconciles_amount_positive CHECK (amount > 0),
    CONSTRAINT chk_partial_reconciles_distinct_sides CHECK (debit_move_id <> credit_move_id)
);

CREATE INDEX IF NOT EXISTS idx_partial_reconciles_company_id_debit_move_id ON accounting.partial_reconciles (company_id, debit_move_id);

