CREATE INDEX IF NOT EXISTS idx_partial_reconciles_full_reconcile_id ON accounting.partial_reconciles (full_reconcile_id) WHERE full_reconcile_id IS NOT NULL;

CREATE INDEX IF NOT EXISTS idx_partial_reconciles_company_id_source_type_source_id ON accounting.partial_reconciles (company_id, source_type, source_id);

